package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.PayrollChangeRequest; import EmployeeManagementSystem.repository.PayrollChangeRequestRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class PayrollChangeRequestServiceImpl implements PayrollChangeRequestService{
 private final PayrollChangeRequestRepository repo; public PayrollChangeRequestServiceImpl(PayrollChangeRequestRepository r){repo=r;}
 public List<PayrollChangeRequest> my(String u){return repo.findByUserIdOrderByCreatedAtDesc(u);} public List<PayrollChangeRequest> all(){return repo.findAllByOrderByCreatedAtDesc();}
 public PayrollChangeRequest create(PayrollChangeRequest x,String u,String n){Set<String> types=Set.of("BANK_ACCOUNT","PAYMENT_METHOD","TAX_REGIME"); if(x.getChangeType()==null||!types.contains(x.getChangeType()))throw new IllegalArgumentException("Invalid payroll change type."); if("BANK_ACCOUNT".equals(x.getChangeType())&&(blank(x.getBankName())||blank(x.getAccountHolderName())||blank(x.getAccountNumber())||blank(x.getIfscCode())))throw new IllegalArgumentException("Bank name, account holder, account number and IFSC are required."); if(repo.existsByUserIdAndChangeTypeAndStatusIn(u,x.getChangeType(),List.of("SUBMITTED","UNDER_REVIEW")))throw new IllegalArgumentException("An active request already exists for this change type."); x.setId(null);x.setRequestNumber("PCR-"+System.currentTimeMillis());x.setUserId(u);x.setEmployeeName(n);x.setStatus("SUBMITTED");return repo.save(x);}
 private boolean blank(String s){return s==null||s.isBlank();}
 public PayrollChangeRequest review(Long id,String s,String c,String r){PayrollChangeRequest x=repo.findById(id).orElseThrow(()->new NoSuchElementException("Payroll change request not found."));if(!Set.of("UNDER_REVIEW","APPROVED","REJECTED").contains(s))throw new IllegalArgumentException("Invalid status.");x.setStatus(s);x.setReviewerUserId(r);x.setReviewerComment(c);x.setReviewedAt(java.time.LocalDateTime.now());return repo.save(x);}
}
